create or replace function catalogue_internal.normalize_identity_text(p_value text)
returns text
language sql
immutable
set search_path=pg_catalog
as $$
  select nullif(regexp_replace(lower(trim(coalesce(p_value,''))), '[^a-z0-9]+', '', 'g'), '');
$$;
revoke all on function catalogue_internal.normalize_identity_text(text) from public,anon,authenticated;
grant execute on function catalogue_internal.normalize_identity_text(text) to service_role;

create or replace function catalogue_internal.refresh_product_identity_keys(p_product_id text)
returns void
language plpgsql
security definer
set search_path=pg_catalog
as $$
declare
  v_product record;
  v_manufacturer_norm text;
  v_category text;
  v_sku text;
  v_mpn text;
  v_model text;
  v_variant text;
begin
  delete from public.catalogue_product_identity_keys
  where product_id=p_product_id
    and key_kind in ('manufacturer_sku','mpn','model_variant');

  select p.*,m.name as manufacturer_name
  into v_product
  from public.catalogue_products p
  left join public.catalogue_manufacturers m on m.id=p.manufacturer_id
  where p.id=p_product_id;

  if not found then return; end if;

  v_manufacturer_norm:=catalogue_internal.normalize_identity_text(v_product.manufacturer_name);
  v_category:=v_product.category::text;
  v_sku:=catalogue_internal.normalize_identity_text(v_product.manufacturer_sku);
  v_mpn:=catalogue_internal.normalize_identity_text(v_product.mpn);
  v_model:=catalogue_internal.normalize_identity_text(v_product.model);
  v_variant:=coalesce(catalogue_internal.normalize_identity_text(v_product.variant),'');

  if v_manufacturer_norm is not null and v_sku is not null then
    insert into public.catalogue_product_identity_keys(product_id,key_kind,key_value,confidence)
    values(p_product_id,'manufacturer_sku',v_category||'|'||v_manufacturer_norm||'|'||v_sku,1)
    on conflict (product_id,key_kind,key_value) do update
      set confidence=excluded.confidence,updated_at=now();
  end if;

  if v_manufacturer_norm is not null and v_mpn is not null then
    insert into public.catalogue_product_identity_keys(product_id,key_kind,key_value,confidence)
    values(p_product_id,'mpn',v_category||'|'||v_manufacturer_norm||'|'||v_mpn,1)
    on conflict (product_id,key_kind,key_value) do update
      set confidence=excluded.confidence,updated_at=now();
  end if;

  if v_manufacturer_norm is not null and v_model is not null then
    insert into public.catalogue_product_identity_keys(product_id,key_kind,key_value,confidence)
    values(p_product_id,'model_variant',
      v_category||'|'||v_manufacturer_norm||'|'||v_model||'|'||v_variant,0.92)
    on conflict (product_id,key_kind,key_value) do update
      set confidence=excluded.confidence,updated_at=now();
  end if;
end;
$$;
revoke all on function catalogue_internal.refresh_product_identity_keys(text)
  from public,anon,authenticated;

