create or replace function catalogue_internal.refresh_product_source_identity_key_trigger()
returns trigger
language plpgsql
security definer
set search_path=pg_catalog
as $$
declare v_key text;
begin
  if tg_op='DELETE' then
    delete from public.catalogue_product_identity_keys
    where product_id=old.product_id
      and key_kind='source_external_id'
      and key_value=old.source_id::text||'|'||
        catalogue_internal.normalize_identity_text(old.external_product_id);
    return null;
  end if;

  if tg_op='UPDATE' then
    delete from public.catalogue_product_identity_keys
    where product_id=old.product_id
      and key_kind='source_external_id'
      and key_value=old.source_id::text||'|'||
        catalogue_internal.normalize_identity_text(old.external_product_id);
  end if;

  v_key:=new.source_id::text||'|'||
    catalogue_internal.normalize_identity_text(new.external_product_id);

  if catalogue_internal.normalize_identity_text(new.external_product_id) is not null then
    insert into public.catalogue_product_identity_keys(product_id,key_kind,key_value,confidence)
    values(new.product_id,'source_external_id',v_key,1)
    on conflict (product_id,key_kind,key_value) do update
      set confidence=excluded.confidence,updated_at=now();
  end if;
  return null;
end;
$$;
revoke all on function catalogue_internal.refresh_product_source_identity_key_trigger()
  from public,anon,authenticated;

